// Minimal normalisation: this workflow exists to prove the path
// Telegram -> n8n -> eva-agent-service -> Agent SDK -> App Server -> LLM,
// not to be Eva's product logic. Text only, no quotas, no onboarding.
const out = [];

for (const item of $input.all()) {
  const update = item.json.body ?? item.json;
  const message = update.message ?? update.edited_message ?? null;
  if (!message || !message.from || !message.text) continue;

  out.push({
    json: {
      chat_id: message.chat.id,
      telegram_id: message.from.id,
      username: message.from.username ?? null,
      first_name: message.from.first_name ?? null,
      last_name: message.from.last_name ?? null,
      language_code: message.from.language_code ?? 'ru',
      text: message.text.trim(),
    },
  });
}

return out;

// Turn the agent service's answer — or its typed error — into one
// Telegram reply. Every error the service produces carries
// {code, message, retryable}, so this needs no HTTP-status guessing.
const source = $('Normalise update').first().json;
const out = [];

for (const item of $input.all()) {
  const status = item.json.statusCode ?? 200;
  const body = item.json.body ?? item.json;

  let reply;
  if (status >= 200 && status < 300) {
    reply = (body.reply || '').trim() || 'Ответ пустой — проверь модель в make configure-letta.';
  } else if (body?.error?.code === 'user_busy') {
    reply = 'Секунду — я ещё отвечаю на предыдущее сообщение.';
  } else if (body?.error?.code === 'app_server_unavailable') {
    reply = 'Letta App Server сейчас недоступен. Попробуй через минуту.';
  } else if (body?.error?.retryable) {
    reply = 'Сервис временно недоступен. Попробуй, пожалуйста, ещё раз.';
  } else {
    reply = 'Ошибка: ' + (body?.error?.code ?? status) + '. Подробности в make logs s=eva-agent-service.';
  }

  out.push({
    json: {
      chat_id: source.chat_id,
      reply,
      status,
      error_code: body?.error?.code ?? null,
      agent_id: body?.agentId ?? null,
      conversation_id: body?.conversationId ?? null,
      duration_ms: body?.durationMs ?? null,
    },
  });
}

return out;
